{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    dists = case['distances']
    n = len(nodes)
    parent = {}
    rank = {}

    def make_set(x):
        parent[x] = x
        rank[x] = 0

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    for node in nodes:
        make_set(node)

    edges = []
    for u, v, d in dists:
        if u > v:
            u, v = v, u
        weight = max(core[u], core[v], d)
        edges.append((weight, u, v))

    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    mst = []
    total = 0.0
    for weight, u, v in edges:
        if union(u, v):
            mst.append([u, v, weight])
            total += weight
            if len(mst) == n - 1:
                break

    if len(mst) != n - 1:
        raise ValueError("Graph is disconnected; cannot form MST")

    return {"mst_edges": mst, "total_weight": total}"
}
